import base64
import json
from pathlib import Path

TEMPLATE = r"""<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Temporal RAG Lab</title>
<style>
:root{font:15px/1.55 system-ui,sans-serif;color:#e6e9ee;background:#101319;color-scheme:dark}*{box-sizing:border-box}body{max-width:1440px;margin:auto;padding:40px 32px}h1{font-size:38px;letter-spacing:-1.5px;line-height:1.15;margin:8px 0 16px}h2{font-size:22px;margin-top:36px}h3{margin:0;font-size:16px}.eyebrow{color:#9fadba;font:12px ui-monospace,monospace;letter-spacing:2px;text-transform:uppercase}.accent{color:#8ee1bd}.muted,small{color:#9fadba}p{max-width:850px}a{color:#8ee1bd}header{border-bottom:1px solid #303641;padding-bottom:24px;margin-bottom:28px}.tag{display:inline-block;font-size:11px;letter-spacing:.6px;text-transform:uppercase;padding:4px 9px;border:1px solid #3a4250;border-radius:20px}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,300px),1fr));gap:16px}.card,.panel{background:#191e27;border:1px solid #303641;border-radius:12px;padding:22px}.card.graphiti{border-top:3px solid #8ee1bd}.card.lightrag-append{border-top:3px solid #b5a2ed}.card.lightrag-replace{border-top:3px solid #f0c58c}.big{font-size:42px;letter-spacing:-2px;font-weight:650;margin:16px 0 0}.stats{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:18px}.stat strong{display:block;font-size:18px}.stat small{font-size:11px}table{width:100%;border-collapse:collapse;font-size:13px}th,td{text-align:left;padding:12px;border-bottom:1px solid #303641}th{color:#9fadba;font-weight:500}select,button,input{font:inherit;background:#191e27;color:#e6e9ee;border:1px solid #485362;padding:9px 12px;border-radius:7px}button{cursor:pointer}button:hover{border-color:#8ee1bd}.toolbar{display:flex;gap:10px;flex-wrap:wrap;margin:20px 0}.probe{border:1px solid #303641;border-radius:10px;background:#191e27;margin-bottom:12px;padding:0 18px}summary{cursor:pointer;padding:16px 0;display:flex;gap:12px;align-items:center;flex-wrap:wrap}.ok{color:#8ee1bd}.fail{color:#f0a5a5}.unknown{color:#f0c58c}.answer{font-size:20px;padding:12px 0;white-space:pre-wrap}.evidence{border-left:2px solid #485362;padding:10px 14px;margin:10px 0;background:#131820;white-space:pre-wrap;overflow-wrap:anywhere}.evidence small{display:block}.error{padding:14px;border:1px solid #a56262;color:#f0a5a5;border-radius:7px;margin:10px 0}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:12px ui-monospace,monospace;max-height:440px;overflow:auto}.foot{margin:36px 0;color:#9fadba;font-size:12px}li{margin:8px 0}code{color:#bdcbd6}#comparison{overflow:auto}label{font-size:12px;color:#9fadba;display:flex;gap:8px;align-items:center}.note{border-left:3px solid #8ee1bd;padding-left:15px;color:#b9c4d0}@media(max-width:900px){.cards{grid-template-columns:1fr}body{padding:24px 16px}h1{font-size:30px}}
</style></head><body>
<header><div class="eyebrow">Temporal RAG Lab / retrieval systems</div><h1>When the facts <span class="accent">change.</span></h1><p class="muted">Graphiti and LightRAG, evaluated against the same dated events and the same OpenRouter models. Inspect the evidence behind every answer.</p><div id="runmeta"></div></header>
<div id="status"></div><div id="scope"></div><div class="cards" id="cards"></div>
<h2>Scores by evaluation dimension</h2><div class="panel" style="overflow:auto" id="dimensions"></div>
<div id="conditions"></div>
<h2>Update tradeoffs</h2><div class="panel" id="comparison"></div>
<h2>Update operations</h2><div class="panel" style="overflow:auto" id="operations"></div>
<h2>Answer & evidence explorer</h2><div class="toolbar"><select id="backend" aria-label="Backend"><option value="">All backends</option></select><select id="scenario" aria-label="Scenario"><option value="">All scenarios</option></select><select id="outcome" aria-label="Outcome"><option value="">All outcomes</option><option value="pass">Passed</option><option value="fail">Failed or errored</option><option value="history">Historical queries</option><option value="retrieval_missing_expected_alias">Retrieval missed expected value</option><option value="context_budget_missing_expected_alias">Expected value omitted by budget</option><option value="answer_used_obsolete_alias">Answer used obsolete value</option><option value="answer_incorrect_despite_expected_alias">Answer wrong despite expected evidence</option></select></div><div id="probes"></div>
<h2>Method & limits</h2><div class="panel"><p id="method"></p><ul id="limits"></ul><details><summary>Configuration & versions</summary><pre id="config"></pre></details><details><summary>Raw API usage (no keys or prompts)</summary><pre id="usage"></pre></details></div><div id="errors"></div><p class="foot">A small experiment, not a universal ranking. Accuracy is an alias check of generated answers. Historical query support and answer quality are separate measurements. Dollar totals contain only costs reported by OpenRouter.</p>
<script>
const report=JSON.parse(new TextDecoder().decode(Uint8Array.from(atob('__REPORT__'),c=>c.charCodeAt(0))));
const $=id=>document.getElementById(id),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pct=x=>x==null?'—':Math.round(x*100)+'%',ms=x=>x==null?'—':(x/1000).toFixed(2)+'s',money=x=>x==null?'unknown':'$'+x.toFixed(4);
$('runmeta').innerHTML=`<span class="tag">${esc(report.status)}</span> <small>${esc(report.run_id)} · ${esc(report.started_at)} · ${esc(report.config.model)}</small>`;
if(report.status!=='complete')$('status').innerHTML=`<p class="note">Run status: ${esc(report.status)}. Check coverage and errors before interpreting these numbers.</p>`;
const dimensionOf=r=>r.probe.dimension&&r.probe.dimension!=='general'?r.probe.dimension:({'owner-change':'temporal','late-arrival':'temporal','release-correction':'retrieval','source-deletion':'lifecycle'}[r.scenario]||'general');
const scored=rows=>rows.filter(r=>r.status==='ok'&&r.scores?.answer_correct!=null),acc=rows=>{const x=scored(rows);return x.length?x.filter(r=>r.scores.answer_correct).length/x.length:null},history=r=>(r.probe.temporal_role||(r.probe.as_of?'historical':'current'))==='historical';
const hasTemporal=report.probes.some(r=>dimensionOf(r)==='temporal'),isSmoke=report.suite.metadata?.kind==='smoke'||report.suite.name==='Changing knowledge';
$('scope').innerHTML='<p class="note">'+(isSmoke?'Exploratory smoke test: the headline below includes only ownership and late-arrival temporal probes. Retrieval coverage and lifecycle checks are scored separately.':hasTemporal?'Temporal workload: compare accuracy by history depth, arrival order, seed and evidence budget below. Small samples are not a universal ranking.':'This report combines diagnostic dimensions; use the separate scores below before drawing conclusions.')+'</p>';
if(report.methodology.measurement_mode==='posthoc-saved-retrieval-context-ablation')$('scope').innerHTML+='<p class="note">Posthoc context diagnostic: reuses saved retrieval from '+esc(report.methodology.source_run_id)+'. No new ingestion or retrieval; this is not an independent replication. Only answer calls are new.</p>';
if(report.publication?.read_only)$('scope').innerHTML+='<p class="note">Read-only published snapshot. Runtime namespaces and per-request logs were removed; no live retrieval index is included.</p>';
$('cards').innerHTML=report.backends.map(b=>{const s=report.summary[b],u=s.usage,rows=scored(report.probes.filter(r=>r.backend===b&&(!hasTemporal||dimensionOf(r)==='temporal'))),cur=rows.filter(r=>!history(r)),hist=rows.filter(history);return `<section class="card ${b}"><div class="eyebrow">${b==='graphiti'?'Temporal fact graph':b==='lightrag-append'?'Document graph · append':'Document graph · replace'}</div><h3>${esc(b)}</h3><div class="big">${pct(acc(rows))}</div><small>${hasTemporal?'Temporal answer':'Diagnostic answer'} accuracy · ${rows.length} scored</small><div class="stats"><div class="stat"><strong>${pct(acc(cur))}</strong><small>Current · n=${cur.length}</small></div><div class="stat"><strong>${pct(acc(hist))}</strong><small>Historical · n=${hist.length}</small></div><div class="stat"><strong>${ms(s.mean_update_ms)}</strong><small>Mean update · all scenarios</small></div><div class="stat"><strong>${money(u.reported_cost_usd)}</strong><small>Reported API cost</small></div></div><p class="muted">${s.probes_completed}/${s.probes_planned} probes completed · ${s.error_count} errors<br>All diagnostic answers: ${pct(s.answer_accuracy)} · n=${s.answers_scored}</p></section>`}).join('');
const dimensions=[...new Set(report.probes.map(dimensionOf))];
$('dimensions').innerHTML='<table><thead><tr><th>Backend</th><th>Dimension</th><th>Correct / scored</th><th>Accuracy</th></tr></thead><tbody>'+report.backends.flatMap(b=>dimensions.map(d=>{const rows=scored(report.probes.filter(r=>r.backend===b&&dimensionOf(r)===d));return `<tr><td>${esc(b)}</td><td>${esc(d)}</td><td>${rows.filter(r=>r.scores.answer_correct).length} / ${rows.length}</td><td>${pct(acc(rows))}</td></tr>`})).join('')+'</tbody></table>';
const conditions=report.backends.flatMap(b=>(report.summary[b].by_condition??[]).map(c=>({backend:b,...c})));
if(conditions.length)$('conditions').innerHTML='<h2>Controlled temporal conditions</h2><div class="panel" style="overflow:auto"><table><thead><tr><th>Backend</th><th>History depth</th><th>Arrival order</th><th>Evidence budget</th><th>Seeds</th><th>Accuracy</th><th>Expected alias in model context</th><th>Accuracy when alias available</th></tr></thead><tbody>'+conditions.map(c=>`<tr><td>${esc(c.backend)}</td><td>${c.history_depth}</td><td>${esc(c.arrival_order)}</td><td>${c.context_tokens} tokens</td><td>${esc(c.seeds.join(', '))}</td><td>${c.correct}/${c.scored} · ${pct(c.accuracy)}</td><td>${pct(c.expected_alias_in_answer_context_rate)}</td><td>${pct(c.accuracy_given_expected_alias_in_context)}</td></tr>`).join('')+'</tbody></table><p class="muted">Alias coverage is a diagnostic, not proof of entailment. Paired probes within a scenario are correlated.</p></div>';
$('comparison').innerHTML='<table><thead><tr><th>Backend</th><th>Update policy</th><th>Native date filter</th><th>Old source history</th><th>Other answer values in context</th><th>Mean retrieval</th></tr></thead><tbody>'+report.backends.map(b=>`<tr><td>${esc(b)}</td><td>${b==='graphiti'?'New episode; reconcile facts':b.endsWith('append')?'Keep every revision':'Delete earlier revisions; reinsert'}</td><td>${b==='graphiti'?'Validity intervals':'Query hint only'}</td><td>${b.endsWith('replace')?'Removed on replacement':'Retained until deletion'}</td><td>${pct(report.summary[b].forbidden_evidence_rate)}</td><td>${ms(report.summary[b].mean_retrieval_ms)}</td></tr>`).join('')+'</tbody></table><p class="muted">Other answer values means literal forbidden-alias exposure. It can include legitimate history, future facts or different roles; it is not a measurement of asserted stale facts.</p>';
$('operations').innerHTML='<table><thead><tr><th>Scenario</th><th>Backend</th><th>Event</th><th>Operation</th><th>Latency</th></tr></thead><tbody>'+report.updates.map(r=>`<tr><td>${esc(r.scenario)}</td><td>${esc(r.backend)}</td><td>${esc(r.step)}</td><td>${esc(r.phase??'write')}</td><td>${ms(r.result.latency_ms)}</td></tr>`).join('')+'</tbody></table>';
for(const b of report.backends)$('backend').insertAdjacentHTML('beforeend',`<option>${esc(b)}</option>`);
for(const s of report.suite.scenarios)$('scenario').insertAdjacentHTML('beforeend',`<option value="${esc(s.id)}">${esc(s.id)}</option>`);
function matchesOutcome(r){const v=$('outcome').value;return !v||(v==='history'?history(r):v==='pass'?r.scores?.answer_correct===true:v==='fail'?r.status==='error'||r.scores?.answer_correct===false:r.scores?.outcome===v)}
function render(){const rows=report.probes.filter(r=>(!$('backend').value||r.backend===$('backend').value)&&(!$('scenario').value||r.scenario===$('scenario').value)&&matchesOutcome(r));$('probes').innerHTML=rows.map(r=>{const pass=r.scores?.answer_correct;return `<details class="probe"><summary><span class="${r.status==='error'||pass===false?'fail':pass===true?'ok':'unknown'}">${r.status==='error'?'ERROR':pass===true?'PASS':pass===false?'FAIL':'UNSCORED'}</span><strong>${esc(r.probe.id)}</strong><small>${esc(r.backend)} · ${esc(r.scenario)} · ${esc(r.probe.category)}</small></summary><p>${esc(r.probe.query)}</p><small>${r.probe.as_of?'As of '+esc(r.probe.as_of):'Latest state'}</small>${r.error?'<div class="error">'+esc(r.error)+'</div>':''}<div class="answer">${esc(r.answer?.answer??'No generated answer')}</div><p class="muted">Expected: ${esc(r.probe.expected_any.join(' / '))} · Forbidden: ${esc(r.probe.forbidden_any.join(' / ')||'none')}</p>${(r.retrieval?.warnings??[]).map(w=>'<p class="note">'+esc(w)+'</p>').join('')}<p class="muted">Diagnostic outcome: ${esc(r.scores?.outcome??'legacy score')}${r.retrieval?.answer_context?' · Evidence tokens: '+r.retrieval.answer_context.tokens_used+'/'+r.retrieval.answer_context.token_budget+' · Omitted records: '+r.retrieval.answer_context.omitted_evidence_ids.length:''}</p><small>Retrieved in ${ms(r.retrieval?.latency_ms)} · ${(r.retrieval?.evidence??[]).length} evidence records · Native temporal filter: ${r.retrieval?.native_temporal_filter?'yes':'no'}</small>${(r.retrieval?.evidence??[]).map(e=>`<div class="evidence"><small>${esc(e.kind)} · ${esc(e.id)}${r.answer?.evidence_ids?.includes(e.id)?' · CITED':''}${r.retrieval?.answer_context?.evidence_ids.includes(e.id)?' · SHOWN TO ANSWER MODEL':''}</small>${esc(e.text)}<small>Valid: ${esc(e.valid_at??'unspecified')} → ${esc(e.invalid_at??'open')}<br>Sources: ${esc(e.source_ids.join(', '))}</small></div>`).join('')}<details><summary>Raw probe record</summary><pre>${esc(JSON.stringify(r,null,2))}</pre></details></details>`}).join('')||'<p class="muted">No probes match this filter.</p>'}
for(const id of ['backend','scenario','outcome'])$(id).addEventListener('change',render);render();
$('method').textContent=report.methodology.scoring;$('limits').innerHTML=report.methodology.limitations.map(l=>'<li>'+esc(l)+'</li>').join('');$('config').textContent=JSON.stringify({config:report.config,versions:report.versions,methodology:report.methodology},null,2);$('usage').textContent=JSON.stringify(report.requests,null,2);$('errors').innerHTML=report.errors.length?'<h2>Errors</h2>'+report.errors.map(e=>'<div class="error">'+esc(e.backend+' / '+e.scenario+': '+e.error)+'</div>').join(''):'';
</script></body></html>"""


def render_html(report: dict) -> str:
    payload = base64.b64encode(json.dumps(report).encode()).decode()
    return TEMPLATE.replace("__REPORT__", payload)


def write_html(report: dict, path: Path):
    temporary = path.with_suffix(".html.tmp")
    temporary.write_text(render_html(report))
    temporary.replace(path)
